rawOutput.content:
        rng,
    )?;
    self.params = Some(p);
    Ok(())
}

fn fit_append_internal(
    &mut self,
    x_new: &ArrayView2<f64>,
    y_new: &ArrayView2<f64>,
    yvar_new: Option<&ArrayView2<f64>>,
    rng: &mut rand::rngs::StdRng,
) -> Result<(), ENNError> {
    if self.model.is_some() {
        let model = self.model.as_mut().expect("model");
        model.add(x_new, y_new, yvar_new)?;
        if let Some(fitter) = self.fitter.as_mut() {
            fitter.tell(x_new, y_new, yvar_new)?;
        }
        self.run_fitter(rng)?;
        return Ok(());
    }
    let mut fitter = ENNFitter::new(self.config.k, self.config.infer_aleatoric_variance);
    fitter.tell(x_new, y_new, yvar_new)?;
    let model = EpistemicNearestNeighbors::new(
        x_new.to_owned(),
        y_new.to_owned(),
        yvar_new.map(|v| v.to_owned()),
        self.config.scale_x,
        self.config.index_driver,

            x,
            &model.train_x().view(),
            model.scale_x,
            &model.x_scale.view(),
        );
        let mut topk_scratch = Vec::with_capacity(n_train);
        let mut float_buf = Vec::with_capacity(n_train);
        for i in 0..n_query {
            let row = dist_mat.row(i);
            let row_slice = row.as_slice().expect("contiguous row");
            let best = topk_indices_from_row_dists_with_buffers(
                row_slice,
                k,
                true,
                &mut topk_scratch,
                &mut float_buf,
            );
            for (j, &t) in best.iter().enumerate() {
                dist2s[[i, j]] = row_slice[t];
                idx[[i, j]] = t as i64;
            }
        }
        return Ok(apply_exclude_nearest(dist2s, idx, exclude_nearest));
    }

    let (dist2s_search, idx_faiss) = model.index().search(x, faiss_search_k as i32, false)?;
    let dist2s_faiss = if tie_break_neighbors {
        dist2s_for_neighbor_indices(model, x, &idx_faiss)
    } else {
        dist2s_search
    };

    let mut tie_scratch = (Vec::<(f64, i64)>::new(), Vec::<(f64, i64)>::new());
    for i in 0..n_query {
        let mut pairs = faiss_pairs_from_row(&dist2s_faiss, &idx_faiss, i);
        if finalize_faiss_pool_topk(
            model,
            x.row(i),
            &mut pairs,
            k,
            tie_break_neighbors,
            None,
            faiss_search_k,
            &mut tie_scratch,
        ) {
            let row_dists_vec = row_dist2s_for_query(model, x.row(i));
            let best = topk_indices_from_row_dists(&row_dists_vec, k, true);
            for (j, &t) in best.iter().enumerate() {
                dist2s[[i, j]] = row_dists_vec[t];
                idx[[i, j]] = t as i64;
            }
            continue;
        }
        for (j, &(d, t)) in pairs.iter().enumerate() {
            dist2s[[i, j]] = d;
            idx[[i, j]] = t;
        }
    }
    Ok(apply_exclude_nearest(dist2s, idx, exclude_nearest))
}

