        if faiss_pool_needs_full_row_scan_from_row(row_dists, k) {
            return true;
        }
        pairs.truncate(k);
        resolve_pool_tie_break_at_cutoff(pairs, k);
        return false;
    }
    if pairs.len() > k {
        pairs.truncate(k);
    }
    if faiss_pool_needs_tie_resolution(pairs, k) {
