        let train_y = array![[0.0], [1.0], [2.0]];
        let model =
            EpistemicNearestNeighbors::new(train_x, train_y, None, false, IndexDriver::Exact)
                .unwrap();
        let precomputed = vec![0.0, 1.0, 4.0];
        let mut cache = None;
        let out = row_dists_for_check(
