    pairs: &mut Vec<(f64, i64)>,
    k: usize,
    tie_break_neighbors: bool,
    ctx: &mut FaissPoolFinalizeCtx<'_>,
) -> bool {
    if !tie_break_neighbors {
        pairs.truncate(k);
