        let query = array![[0.0]];
        let mut escalate = vec![(0.0, 0i64), (0.0, 1), (0.0, 2), (1.0, 3)];
        let pool_len = escalate.len();
        let mut scratch = (Vec::new(), Vec::new());
        assert!(!finalize_faiss_pool_topk(
            &model,
