                .unwrap();
        let mut resolve = vec![(0.0, 1i64), (0.0, 0), (1.0, 2), (4.0, 3)];
        let pool_len = resolve.len();
        let mut scratch = (Vec::new(), Vec::new());
        assert!(!finalize_faiss_pool_topk(
            &model2,
            query.row(0),
            &mut resolve,
            2,
            true,
            None,
            pool_len,
            &mut scratch,
        ));
        assert_eq!(
            resolve.iter().take(2).map(|p| p.1).collect::<Vec<_>>(),
            vec![0, 1]
        );
    }

